create schema "realtime" authorization "supabase_admin";

grant usage on schema "realtime" to "anon", "authenticated", "service_role";

grant create, usage on schema "realtime" to "supabase_realtime_admin";

create table "realtime"."messages" (
  "topic"          text                        not null,
  "extension"      text                        not null,
  "payload"        jsonb,
  "event"          text,
  "private"        boolean,
  "updated_at"     timestamp without time zone not null,
  "inserted_at"    timestamp without time zone not null,
  "id"             uuid                        not null,
  "binary_payload" bytea,
  "skip_broadcast" boolean                     not null,
  "expires_at"     timestamp without time zone
) partition by range (inserted_at);

alter table "realtime"."messages"
  enable row level security;

alter table "realtime"."messages"
  owner to "supabase_realtime_admin";

alter table "realtime"."messages"
  alter column "id" set default gen_random_uuid();

alter table "realtime"."messages"
  alter column "inserted_at" set default timezone('utc'::text, clock_timestamp());

alter table "realtime"."messages"
  alter column "private" set default false;

alter table "realtime"."messages"
  alter column "skip_broadcast" set default false;

alter table "realtime"."messages"
  alter column "updated_at" set default timezone('utc'::text, clock_timestamp());

